<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\Review;use App\Models\ReviewReport;use Illuminate\Http\Request;
class ReviewController extends Controller{public function index(Request $r){$reviews=Review::with(['product','user'])->withCount('reports')->when($r->filled('status'),fn($q)=>$q->where('status',$r->string('status')))->latest()->paginate(20)->withQueryString();return view('admin.reviews.index',compact('reviews'));}public function moderate(Request $r,Review $review){$d=$r->validate(['status'=>['required','in:published,hidden,rejected'],'moderation_reason'=>['nullable','string','max:1000']]);$review->update($d+['moderated_by'=>$r->user()->id,'moderated_at'=>now()]);$review->reports()->update(['status'=>'reviewed']);$this->rating($review);return back()->with('status','Решение по отзыву сохранено.');}private function rating(Review $review):void{$q=$review->product->reviews()->published();$review->product->update(['rating_avg'=>round($q->avg('rating')??0,2),'rating_count'=>$q->count()]);}}
